package org.apache.commons.math.util;

import java.io.*;
import java.math.*;
import java.math.BigDecimal;
import java.util.*;
import java.util.Arrays;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;

public class MathUtils_gcd_TriageGen1Test {









    @Test
    public void testGcdOddAndEven() {
        // Testing B2/B3 logic (t initialization)
        // u is odd, v is even (t replaces v)
        // Since u is odd, it stays u. t = v.
        assertEquals(1, MathUtils.gcd(3, 4));

        // u is even, v is odd (t replaces u)
        // Since u is even, u becomes -(u/2).
        assertEquals(1, MathUtils.gcd(4, 3));
    }






}

